INSERT INTO public.site_copy_drafts(key,title,body,eyebrow)
VALUES
('policy.terms.charges','Charges, taxes and payment processing',
'The price shown before payment includes lodging, applicable host fees, selected extras, taxes and a separately identified Find A Place guest service fee when applicable. For new direct bookings, the standard Find A Place fee is 7% of discounted lodging only; cleaning, pet, optional extras and lodging taxes are excluded. Any verified partner rate is disclosed at checkout. Payments are direct charges on the host''s connected Stripe account. Hosts are responsible for Stripe processing costs and their lodging tax reporting and remittance. Find A Place does not collect or remit those lodging taxes. Reservations made under earlier host-paid arrangements retain the fee terms and amounts saved when they were booked.',null),
('policy.terms.cancellations','Cancellations, refunds and guest service fees',
'Guests may request cancellations or refunds under the host''s property terms accepted when the reservation was made, subject to applicable law. A request does not guarantee a refund. For guest-paid-fee bookings the disclosed Find A Place service fee is generally retained after payment; the host can authorize a full or partial guest-charge refund under the reservation terms, in which case the connected host charge funds the refund while Find A Place''s application fee is not reversed. The host is responsible for the amount it authorizes, including any guest fee refunded from the host charge. Processor fees may not be returned. No cancellation or refund changes fees on previous reservations retroactively.',null),
('policy.terms.changes','Reservation changes',
'Guests may request changes to dates, occupancy or other booking details. The reservation does not change until the host approves and applies the request. A change does not automatically authorize another charge or refund. Any refund must be approved separately. Service-fee treatment follows the policy and fee snapshot saved with the original reservation and applicable law.',null),
('policy.host.cancellations','Cancellations, refunds and platform fees',
'Hosts decide guest cancellation and refund requests under the property terms accepted at booking, subject to applicable law. New guest-paid-fee reservations do not incur an additional host-paid Find A Place commission. If the host approves a partial or full refund, it is funded from the host''s connected charge. Find A Place''s already-earned application fee is generally not reversed, even when the host refunds a guest the service-fee portion of a charge. Stripe processing fees may also be non-refundable. The platform does not recalculate old bookings under a new fee model.',null),
('policy.cancellation.commission','Find A Place service fee on cancellations',
'For new guest-paid-fee bookings, a disclosed Find A Place service fee is charged to the guest on eligible discounted lodging. The fee is normally retained when a paid reservation is cancelled or changed, except where law or the booking terms require otherwise. A host may choose to fund a guest refund that includes this amount without reversing Find A Place''s application fee. Earlier host-paid-commission reservations keep their original agreed terms.',null),
('policy.cancellation.refunds','Host-approved guest refunds',
'If the host approves a refund, it is issued against the host''s connected payment charge. The host is financially responsible for any amount authorized, including eligible taxes and any guest service fee it chooses or is required to return. Find A Place''s application fee is not automatically reversed by a host refund. Stripe processing charges and refund timing follow the processor''s policies. Applicable non-waivable consumer rights remain in effect.',null),
('policy.cancellation.changes','Reservation changes',
'Changing dates, guests or stay details does not automatically create a refund. A host may separately approve a refund or additional charge. The original booking''s fee snapshot and cancellation terms govern, subject to applicable law; the platform does not retrospectively change prior booking fees.',null)
ON CONFLICT (key) DO NOTHING;
